<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';$p=sk1380_require_provider();$ent=sk1380_entitlements((int)$p['id']);$fastEffective=!empty($ent['fast_service'])&&!empty($p['fast_service_enabled']);$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();if(sk1380_month_quote_count((int)$p['id'])>=$ent['monthly_quote_limit'])throw new RuntimeException('Monthly quote limit reached for your package.');$rid=(int)$_POST['request_id'];$amount=max(0,(float)$_POST['amount']);$visit=max(0,(float)($_POST['visit_fee']??0));$note=trim((string)($_POST['message']??''));$q=sk1380_db()->prepare('SELECT r.* FROM service_requests_v1380 r WHERE r.tenant_id=? AND r.id=? AND r.status IN("open","quoted") AND (r.preferred_provider_id IS NULL OR r.preferred_provider_id=?) AND (r.urgency<>"fast" OR ?=1) AND EXISTS(SELECT 1 FROM service_provider_categories_v1380 pc WHERE pc.tenant_id=r.tenant_id AND pc.provider_id=? AND pc.category_id=r.category_id) LIMIT 1');$q->execute([sk1380_tid(),$rid,$p['id'],$fastEffective?1:0,$p['id']]);if(!$q->fetch())throw new RuntimeException('Request is not available for your approved categories.');sk1380_db()->prepare('INSERT INTO service_quotes_v1380(tenant_id,request_id,provider_id,amount,visit_fee,message,arrival_minutes,valid_until,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,"submitted",NOW(),NOW()) ON DUPLICATE KEY UPDATE amount=VALUES(amount),visit_fee=VALUES(visit_fee),message=VALUES(message),arrival_minutes=VALUES(arrival_minutes),valid_until=VALUES(valid_until),status="submitted",updated_at=NOW()')->execute([sk1380_tid(),$rid,$p['id'],$amount,$visit,$note?:null,($_POST['arrival_minutes']??'')!==''?(int)$_POST['arrival_minutes']:null,date('Y-m-d H:i:s',strtotime('+2 days'))]);sk1380_db()->prepare('UPDATE service_requests_v1380 SET status="quoted",quote_count=(SELECT COUNT(*) FROM service_quotes_v1380 sq WHERE sq.tenant_id=service_requests_v1380.tenant_id AND sq.request_id=service_requests_v1380.id AND sq.status="submitted"),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([sk1380_tid(),$rid]);$msg='Quote submitted.';}catch(Throwable $e){$err=$e->getMessage();}}$q=sk1380_db()->prepare('SELECT r.*,c.name category_name,c.icon,(SELECT sq.amount FROM service_quotes_v1380 sq WHERE sq.tenant_id=r.tenant_id AND sq.request_id=r.id AND sq.provider_id=? LIMIT 1) my_quote FROM service_requests_v1380 r JOIN service_categories_v1380 c ON c.id=r.category_id WHERE r.tenant_id=? AND r.status IN("open","quoted") AND (r.preferred_provider_id IS NULL OR r.preferred_provider_id=?) AND (r.urgency<>"fast" OR ?=1) AND EXISTS(SELECT 1 FROM service_provider_categories_v1380 pc WHERE pc.tenant_id=r.tenant_id AND pc.provider_id=? AND pc.category_id=r.category_id) ORDER BY r.urgency="fast" DESC,r.id DESC LIMIT 100');$q->execute([$p['id'],sk1380_tid(),$p['id'],$fastEffective?1:0,$p['id']]);$rows=$q->fetchAll(PDO::FETCH_ASSOC)?:[];sk1380_shell('Provider Leads','provider-leads');?><section class="dash-hero"><div><span class="eyebrow">MATCHING SERVICE REQUESTS</span><h1>Local Job Leads</h1><p><?=sk1380_month_quote_count((int)$p['id'])?> / <?=$ent['monthly_quote_limit']?> monthly quotes used</p></div><a href="/provider/services.php">Dashboard</a></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="lead-list"><?php foreach($rows as $r):?><article><header><span><?=sk1380_h($r['icon'].' '.$r['category_name'])?></span><?php if($r['urgency']==='fast'):?><b>⚡ FAST REQUEST</b><?php endif;?></header><h2><?=sk1380_h($r['title'])?></h2><p><?=nl2br(sk1380_h($r['description']))?></p><small><?=sk1380_h($r['area'])?> · preferred <?=sk1380_h(($r['preferred_date']?:'flexible').' '.($r['preferred_time']?:''))?></small><form method="post" class="quote-form"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="request_id" value="<?=$r['id']?>"><label>Your quote (PKR)<input type="number" min="0" name="amount" required value="<?=sk1380_h($r['my_quote']??'')?>"></label><label>Visit fee<input type="number" min="0" name="visit_fee" value="0"></label><label>Arrival estimate (minutes)<input type="number" min="0" name="arrival_minutes"></label><label>Message<input name="message" placeholder="What is included in your quote?"></label><button><?=$r['my_quote']!==null?'Update Quote':'Send Quote'?></button></form></article><?php endforeach;?></div><?php sk1380_end();